                                                                                                                                                                                                                                                                                                                                                                                                                                      app.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                        <header class="chat-header">
                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="avatar">R</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="header-info">
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h1>Ryan AI</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span>Asistente personal · Vista inicial</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </header>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <main class="chat-messages" id="messages">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="message ryan">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ¡Hola! Soy Ryan AI. Ya estoy listo para probar nuestra interfaz. Escríbeme algo aquí abajo.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </main>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <form class="chat-form" id="chatForm">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type="text"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      id="messageInput"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            class="chat-input"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder="Escribe un mensaje..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        autocomplete="off"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              required
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button type="submit" class="send-btn">Enviar</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const messagesContainer = document.querySelector('#messages');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const chatForm = document.querySelector('#chatForm');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const messageInput = document.querySelector('#messageInput');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function addMessage(text, sender) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const bubble = document.createElement('div');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            bubble.className = `message ${sender}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              bubble.textContent = text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                messagesContainer.appendChild(bubble);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  messagesContainer.scrollTop = messagesContainer.scrollHeight;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  chatForm.addEventListener('submit', async (event) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    event.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const text = messageInput.value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!text) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          addMessage(text, 'user');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const texto = messageInput.value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!texto) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const respuesta = await pedirRespuestaRyan(texto);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
const messagesContainer = document.querySelector("#messages");
if (messagesContainer) {
  const replyEl = document.createElement("div");
    replyEl.textContent = respuesta;
      messagesContainer.appendChild(replyEl);                                                                                                                                                                                                                                                           
}
});                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                              
const WORKER_URL = "https://ryania.nion22470.workers.dev";

async function pedirRespuestaRyan(mensaje) {
  const res = await fetch(WORKER_URL, {
      method: "POST",
          headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ message: mensaje })
                });

                  const data = await res.json();

                    if (!res.ok) {
                        throw new Error(data.error || "Error al hablar con Ryan AI");
                          }

                            return data.reply;
                            }
